const j = $input.first().json;
const HOST_CHARS = new RegExp('^[a-z0-9.-]+$');
function pick() {
  for (let i = 0; i < arguments.length; i++) {
    const v = j[arguments[i]];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
}
const FREE = ['gmail.com', 'googlemail.com', 'yahoo.com', 'yahoo.fr', 'hotmail.com', 'hotmail.fr', 'outlook.com', 'outlook.fr', 'live.com', 'live.fr', 'msn.com', 'icloud.com', 'me.com', 'orange.fr', 'wanadoo.fr', 'free.fr', 'sfr.fr', 'neuf.fr', 'laposte.net', 'bbox.fr', 'protonmail.com', 'proton.me', 'gmx.fr', 'gmx.com', 'aol.com'];
function hostOf(u) {
  let s = String(u || '').trim().toLowerCase();
  if (!s) return '';
  const p = s.indexOf('://');
  if (p >= 0) s = s.slice(p + 3);
  let end = s.length;
  ['/', '?', '#'].forEach(function (c) { const i = s.indexOf(c); if (i >= 0 && i < end) end = i; });
  s = s.slice(0, end);
  const at = s.lastIndexOf('@');
  if (at >= 0) s = s.slice(at + 1);
  const colon = s.indexOf(':');
  if (colon >= 0) s = s.slice(0, colon);
  while (s.slice(-1) === '.') s = s.slice(0, -1);
  return s;
}
function isPublicHost(h) {
  if (!h || h.indexOf('.') < 0 || !HOST_CHARS.test(h)) return false;
  if (h === 'localhost' || h.slice(-6) === '.local' || h.slice(-9) === '.internal' || h.slice(-4) === '.lan' || h.slice(-5) === '.home') return false;
  const parts = h.split('.');
  if (parts.some(function (x) { return x === ''; })) return false;
  if (parts.every(function (x) { return !isNaN(Number(x)); })) return false;
  return true;
}
const email = pick('E-mail professionnel', 'email').toLowerCase();
const emailDomain = email.split('@')[1] || '';
const freeEmail = FREE.indexOf(emailDomain) >= 0;
let host = hostOf(pick('Site web', 'website'));
if (!isPublicHost(host) && !freeEmail && isPublicHost(emailDomain)) host = emailDomain;
const canFetch = isPublicHost(host);
const fullName = pick('Nom complet', 'name');
const words = fullName.split(' ').filter(function (w) { return w; });
return [{ json: {
  submitted_at: j.submittedAt || DateTime.now().toISO(),
  full_name: fullName,
  first_name: words[0] || '',
  last_name: words.slice(1).join(' '),
  email: email,
  email_domain: emailDomain,
  free_email: freeEmail,
  company: pick('Entreprise', 'company'),
  website: canFetch ? 'https://' + host : '',
  can_fetch_site: canFetch,
  job_title: pick('Poste', 'job_title'),
  company_size: pick("Taille de l'entreprise", 'company_size'),
  need: pick('Votre besoin', 'need').slice(0, 3000),
  budget: pick('Budget mensuel', 'budget'),
  timeline: pick('Délai', 'timeline')
} }];

const lead = $('Normaliser la demande').first().json;
const QUOTES = String.fromCharCode(34) + String.fromCharCode(39);
let html = '';
let siteError = '';
if (!lead.can_fetch_site) {
  siteError = 'Aucun site professionnel à lire';
} else {
  try {
    const r = $('Lire le site du prospect').first().json;
    if (r.error) siteError = typeof r.error === 'string' ? r.error : String(r.error.message || 'site injoignable');
    else html = String(r.data || '');
  } catch (e) {
    siteError = 'Site non consulté';
  }
}
const SPACES = new RegExp('[' + String.fromCharCode(9, 10, 13, 160) + ' ]+', 'g');
const TAGS = new RegExp('<[^>]+>', 'g');
function decode(s) {
  return String(s || '').split('&amp;').join('&').split('&nbsp;').join(' ').split('&#39;').join(String.fromCharCode(39)).split('&rsquo;').join(String.fromCharCode(39)).split('&quot;').join(String.fromCharCode(34)).split('&eacute;').join('é').split('&egrave;').join('è').split('&agrave;').join('à');
}
function tidy(s) { return decode(String(s || '').replace(TAGS, ' ')).replace(SPACES, ' ').trim(); }
function firstMatch(re) { const m = html.match(re); return m ? m[1] : ''; }
const title = tidy(firstMatch(new RegExp('<title[^>]*>([^<]*)</title>', 'i')));
let description = '';
const metaTag = html.match(new RegExp('<meta[^>]+name=[' + QUOTES + ']description[' + QUOTES + '][^>]*>', 'i'));
if (metaTag) {
  const c = metaTag[0].match(new RegExp('content=[' + QUOTES + ']([^' + QUOTES + ']*)', 'i'));
  description = c ? tidy(c[1]) : '';
}
const h1 = tidy(firstMatch(new RegExp('<h1[^>]*>([^]*?)</h1>', 'i')));
let body = html;
['script', 'style', 'noscript', 'svg', 'nav', 'footer', 'header'].forEach(function (t) {
  body = body.replace(new RegExp('<' + t + '[^>]*>[^]*?</' + t + '>', 'gi'), ' ');
});
const excerpt = tidy(body).slice(0, 2500);
return [{ json: {
  site_error: siteError,
  dossier: {
    contact: { nom: lead.full_name, poste: lead.job_title, email_professionnel: !lead.free_email, domaine_email: lead.email_domain },
    entreprise: { nom: lead.company, site: lead.website, taille_declaree: lead.company_size },
    demande: { besoin: lead.need, budget_mensuel: lead.budget, delai: lead.timeline },
    site_web: siteError ? { indisponible: siteError } : { titre: title.slice(0, 200), description: description.slice(0, 400), h1: h1.slice(0, 200), extrait: excerpt }
  }
} }];

const lead = $('Normaliser la demande').first().json;
const site = $('Extraire le contenu du site').first().json;
const cfg = $('Configuration').first().json;
const raw = $input.first().json;

function claudeText(r) {
  if (!r || !Array.isArray(r.content)) return '';
  return r.content.filter(function (b) { return b && b.type === 'text'; }).map(function (b) { return b.text || ''; }).join('');
}
function claudeError(r) {
  if (!r || typeof r !== 'object') return 'aucune réponse';
  if (typeof r.error === 'string') return r.error;
  if (r.error && r.error.message) return String(r.error.message);
  if (r.stop_reason === 'refusal') return 'refus du modèle';
  if (r.stop_reason === 'max_tokens') return 'réponse coupée';
  return '';
}
function parseJson(t) {
  const i = t.indexOf('{'), k = t.lastIndexOf('}');
  if (i < 0 || k <= i) return null;
  try { return JSON.parse(t.slice(i, k + 1)); } catch (e) { return null; }
}
function clean(v) {
  const em = String.fromCharCode(8212), en = String.fromCharCode(8211);
  return String(v || '').split(' ' + em + ' ').join(', ').split(' ' + en + ' ').join(', ').split(em).join(', ').split(en).join('-').trim();
}
function key(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]/g, ''); }

const BUDGET = {};
BUDGET[key('Plus de 10 000 €')] = 25;
BUDGET[key('3 000 à 10 000 €')] = 20;
BUDGET[key('1 000 à 3 000 €')] = 12;
BUDGET[key('Je ne sais pas encore')] = 8;
BUDGET[key('Moins de 1 000 €')] = 4;
const DELAI = {};
DELAI[key('Ce mois-ci')] = 15;
DELAI[key('Ce trimestre')] = 10;
DELAI[key('Plus tard')] = 3;

const budgetPts = BUDGET[key(lead.budget)] || 0;
const delaiPts = DELAI[key(lead.timeline)] || 0;
const emailPts = lead.free_email ? 0 : 10;
const rules = budgetPts + delaiPts + emailPts;

const text = claudeText(raw);
const ai = text ? parseJson(text) : null;
const aiOk = !!(ai && isFinite(Number(ai.score_adequation)));
const fit = aiOk ? Math.max(0, Math.min(100, Math.round(Number(ai.score_adequation)))) : null;
const score = aiOk ? Math.round(fit / 2 + rules) : Math.min(100, rules * 2);
const hot = Number(cfg.hot_threshold) || 70;
const segment = score >= hot ? 'chaud' : (score >= 40 ? 'tiède' : 'froid');

const reasons = (aiOk && Array.isArray(ai.raisons) ? ai.raisons.map(clean) : []).slice(0, 3);
reasons.push('Budget : ' + (lead.budget || 'non précisé') + ' (' + budgetPts + ' pts), délai : ' + (lead.timeline || 'non précisé') + ' (' + delaiPts + ' pts)');
reasons.push(lead.free_email ? 'E-mail personnel : entreprise à confirmer (0 pt)' : 'E-mail professionnel ' + lead.email_domain + ' (10 pts)');

const anomalies = [];
if (!aiOk) anomalies.push("Analyse de Claude indisponible (" + (claudeError(raw) || 'réponse illisible') + "). Score calculé sur le budget, le délai et l'e-mail seulement.");

return [{ json: Object.assign({}, lead, {
  score: score,
  fit_score: fit,
  rules_score: rules,
  segment: segment,
  ai_ok: aiOk,
  resume: aiOk ? clean(ai.resume) : '',
  raisons: reasons,
  risques: aiOk && Array.isArray(ai.risques) ? ai.risques.map(clean).slice(0, 2) : [],
  next_action: aiOk && ai.prochaine_action ? clean(ai.prochaine_action) : (segment === 'chaud' ? 'Rappeler sous 24 h ouvrées.' : 'Envoyer une réponse personnalisée par e-mail.'),
  angle: aiOk ? clean(ai.angle) : '',
  site_error: site.site_error,
  anomalies: anomalies
}) }];

const s = $('Calculer le score').first().json;
const cfg = $('Configuration').first().json;
const h = $input.first().json;
const NL = String.fromCharCode(10);

function esc(v) { return String(v === null || v === undefined ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function li(list) { return (list || []).map(function (x) { return '<li>' + esc(x) + '</li>'; }).join(''); }

let rowId = null;
try { rowId = $('Enregistrer la demande').first().json.id || null; } catch (e) { rowId = null; }

let hubspotId = '';
let hubspotError = '';
if (h && h.error) hubspotError = typeof h.error === 'string' ? h.error : String(h.error.message || 'erreur HubSpot');
else hubspotId = String((h && (h.vid || h.canonicalVid || h.id)) || '');
if (!hubspotId && !hubspotError) hubspotError = 'contact non confirmé par HubSpot';

const anomalies = (s.anomalies || []).slice();
if (hubspotError) anomalies.push('HubSpot : ' + hubspotError + '. Le lead reste enregistré dans la table Leads qualifies.');
if (!rowId) anomalies.push("La demande n'a pas pu être enregistrée dans la table Leads qualifies.");

const link = cfg.hubspot_portal_id && hubspotId ? 'https://app.hubspot.com/contacts/' + cfg.hubspot_portal_id + '/record/0-1/' + hubspotId : '';
const tone = s.segment === 'chaud' ? '#b42318' : (s.segment === 'tiède' ? '#b54708' : '#5b6472');
const H3 = '<h3 style="font-size:15px;margin:18px 0 6px">';
const UL = '<ul style="margin:0;padding-left:20px;line-height:1.55">';

const salesHtml = '<div style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#1d2430;max-width:600px">' +
  '<p style="margin:0;font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:' + tone + ';font-weight:700">Lead ' + esc(s.segment) + ' · ' + s.score + '/100</p>' +
  '<h2 style="margin:4px 0 2px;font-size:22px">' + esc(s.company) + '</h2>' +
  '<p style="margin:0 0 16px;color:#5b6472">' + esc(s.full_name) + (s.job_title ? ', ' + esc(s.job_title) : '') + ' · <a href="mailto:' + esc(s.email) + '">' + esc(s.email) + '</a>' + (s.website ? ' · <a href="' + esc(s.website) + '">' + esc(s.website.split('https://').join('')) + '</a>' : '') + '</p>' +
  (s.resume ? '<p style="line-height:1.55;margin:0 0 14px">' + esc(s.resume) + '</p>' : '') +
  (s.angle ? '<p style="padding:12px 14px;background:#eef6f1;border-radius:6px;line-height:1.5;margin:0"><strong>Première phrase à dire</strong><br>' + esc(s.angle) + '</p>' : '') +
  H3 + 'Pourquoi ce score</h3>' + UL + li(s.raisons) + '</ul>' +
  (s.risques && s.risques.length ? H3 + 'Points à vérifier</h3>' + UL + li(s.risques) + '</ul>' : '') +
  H3 + 'Sa demande</h3><p style="white-space:pre-wrap;line-height:1.55;margin:0">' + esc(s.need) + '</p>' +
  '<p style="color:#5b6472;font-size:13px;margin-top:10px">Budget : ' + esc(s.budget || 'non précisé') + ' · Délai : ' + esc(s.timeline || 'non précisé') + ' · Taille : ' + esc(s.company_size || 'non précisée') + '</p>' +
  '<p style="margin-top:16px"><strong>Prochaine action :</strong> ' + esc(s.next_action) + '</p>' +
  (link ? '<p><a href="' + esc(link) + '" style="display:inline-block;padding:10px 16px;background:#1d2430;color:#ffffff;border-radius:6px;text-decoration:none">Ouvrir la fiche HubSpot</a></p>' : '') +
  (anomalies.length ? '<p style="padding:10px 14px;background:#fff4e5;border-radius:6px;font-size:13px">' + anomalies.map(esc).join('<br>') + '</p>' : '') +
  '</div>';

const anomalyHtml = '<div style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#1d2430;max-width:600px">' +
  '<p>Une demande a été traitée avec des anomalies :</p>' + UL + li(anomalies) + '</ul>' +
  '<p style="margin-top:14px">Lead : <strong>' + esc(s.company) + '</strong>, ' + esc(s.full_name) + ', ' + esc(s.email) + '<br>Score : ' + s.score + '/100 (' + esc(s.segment) + ')</p>' +
  '<p>Vérifiez les connexions dans n8n. La demande complète est dans la table Leads qualifies.</p></div>';

const taskBody = ['Score ' + s.score + '/100 (' + s.segment + ').', s.resume, s.angle ? 'Première phrase : ' + s.angle : '', 'Raisons : ' + (s.raisons || []).join(' ; '), 'Besoin : ' + s.need, 'Prochaine action : ' + s.next_action].filter(function (x) { return x; }).join(NL + NL);

return [{ json: {
  row_id: rowId || -1,
  hubspot_id: hubspotId,
  is_hot: s.segment === 'chaud',
  has_anomaly: anomalies.length > 0,
  reasons_text: (s.raisons || []).join(' ; '),
  error_text: anomalies.join(' '),
  task_subject: 'Rappeler ' + s.full_name + ' (' + s.company + '), lead ' + s.score + '/100',
  task_body: taskBody,
  sales_subject: 'Lead chaud ' + s.score + '/100 : ' + s.company + (s.timeline ? ', ' + s.timeline.toLowerCase() : ''),
  sales_html: salesHtml,
  anomaly_subject: 'Qualification de lead : anomalie sur ' + s.company,
  anomaly_html: anomalyHtml
} }];
